using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PlagueDoctorAchievementData", menuName = "Data/Achievements/PlagueDoctorAchievementData")]
public class PlagueDoctorAchievementData : AchievementData
{
	[SerializeField]
	private PlayerDiceInventoryData[] playerDiceInventoryData;

	[SerializeField]
	private Dice plagueDice;

	protected override bool UnlockCustomRequirementCheck()
	{
		int num = 0;
		for (int i = 0; i < playerDiceInventoryData.Length; i++)
		{
			num += playerDiceInventoryData[i].GetSpecificDiceAmount(plagueDice.DiceName);
		}
		return num >= base.AchievementVariableAmount;
	}
}
